) AS (
  VALUES 
    (493::BIGINT, 'Excelente profesor, llevar este curso con el fue lo mejor, explica super bien, ayuda mucho al estudiante y es muy paciente, para un curso tan pesado como este, el es el profesor indicado'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'dbfcf5a455f3da46cc06698734d75cec72183f38e06c5868108c720f7d65c18f'::TEXT, ARRAY[935]::BIGINT[]),
    (493::BIGINT, 'es un excelente profesor y persona, explica hasta lo más básico y no se salta ni un solo paso. sin embargo, si califica muy duro y hay que detallarle TODO en los examenes sino penalisa. es excelente y se aprende, nada más que si califica medio brusco.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2026-06-26T00:00:00+00:00'::TIMESTAMPTZ, '670e07ba10ba063d127f3a65fdabd42404584d9a78f8891742ff3527a6342839'::TEXT, ARRAY[935]::BIGINT[]),
    (493::BIGINT, 'De lo mejor que tiene la escuela de mate. Explica con muchísima claridad y paciencia, de verdad que no se brinca ningún paso. Califica bien y los quices que hace son accesibles, con estudiar con las prácticas que deja es más que suficiente. Matricule sin miedo, es buenísimo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-06-23T00:00:00+00:00'::TIMESTAMPTZ, '918463cecd42d5919f6a08b2ffb927b524e735fbfb881921a7998193c92f530d'::TEXT, ARRAY[935]::BIGINT[]),
    (493::BIGINT, 'El mejor profe de cálculo de uno podría pedir. Los apuntes que el hace en clase siempre los comparte, explica la teoría y luego los ejemplos con gran claridad, muy amable a la hora de explicar si uno no entiende algo y califica super suave. No hace muchos quices pero los que hace son muy sencillos.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-02-13T00:00:00+00:00'::TIMESTAMPTZ, '68a220903ad314c32135f5d88c97ef814e3bc6679c6f32feeead4c835d608220'::TEXT, ARRAY[605]::BIGINT[]),
    (493::BIGINT, 'El profe sólo dejó tareas, por tanto, nada más era ponerle a los exámenes, y el profe es buena nota calificando. Ah, y un crack explicando :)'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-28T00:00:00+00:00'::TIMESTAMPTZ, 'e715d32a21fb6e4e9af08532f5914c7630c2b805c96d8ae3aa19cea99face0c4'::TEXT, ARRAY[935]::BIGINT[]),
    (493::BIGINT, 'Excelente profe, cualquier materia que da es excelente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-12-05T00:00:00+00:00'::TIMESTAMPTZ, '3b714c533cfc74a03b0eab82c5fcb1dc5e759b420e9053755a80952a72a3848c'::TEXT, ARRAY[605]::BIGINT[]),
    (493::BIGINT, 'Un crack para este curso, explica cada detalle y no asume nada; explica absolutamente todo lo necesario. Sus evaluaciones son bastantes manejables (con sólo estudiar lo visto en clase, se pasa). Espero con ansias, verlo en otro curso.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2025-12-02T00:00:00+00:00'::TIMESTAMPTZ, '278796394559c085c9d2164c417ff0e26a2e649d46a9a8f7146d7c6c5bf0edcf'::TEXT, ARRAY[605]::BIGINT[]),
    (493::BIGINT, 'Bastante relajado y tranquilo el curso. El profesor lo hace ver todo fácil. Muy accesible en las evaluaciones. :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'abe40787817c9b7d2012a178c4d35dada979ba6563692e4079c3180ce399da43'::TEXT, ARRAY[923]::BIGINT[]),
    (493::BIGINT, 'Es un excelente profesor, saca el tiempo para que el estudiante aprenda y entienda, hace ver la materia sencilla'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2025-11-24T00:00:00+00:00'::TIMESTAMPTZ, '8ac14b6b73853df4170f358323af18d1d966228644adce22626737c34e549b54'::TEXT, ARRAY[563]::BIGINT[]),
    (493::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2025-11-16T00:00:00+00:00'::TIMESTAMPTZ, 'ddc7f5dadde3f0be9cc4a22daf1ec0a9e5ce3e0a6ec854c1c71e6284d4b94e0e'::TEXT, ARRAY[923]::BIGINT[]),
    (493::BIGINT, 'Es bastante pro para cálculo diferencial, si es la primera vez que lo lleva mejor, pues él explica cada detalle necesario para el curso. Muy respetado en sus clases y muy atento en la consulta. :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-11-11T00:00:00+00:00'::TIMESTAMPTZ, '43429d66a7ecee048b0a11aa48caed8e899baed905e61153f1575ba23720c278'::TEXT, ARRAY[923, 634, 605]::BIGINT[]),
    (493::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2025-11-03T00:00:00+00:00'::TIMESTAMPTZ, 'ddb5be5abed34719cf1f816638eb3fdd558e96b9c4630afe00c26e61753f7696'::TEXT, ARRAY[935]::BIGINT[]),
    (493::BIGINT, 'Es bastante relax con sus evaluaciones, y lo más importante, muuuy bien. Sus folletos son muy completos y ayudan bastante a prepararse a los exámenes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-10-28T00:00:00+00:00'::TIMESTAMPTZ, '58efb32998b90bc68acd359d85fd1a6aedf8227a4ed16230294647225adab08e'::TEXT, ARRAY[923]::BIGINT[]),
    (493::BIGINT, 'Discreta no es fácil, pero este profe lo hace más ameno la comprensión de los temas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-10-19T00:00:00+00:00'::TIMESTAMPTZ, '8a064ff412a39067d23cff4241fd189e04c007205cfcb9a9eac4ab9bb136257e'::TEXT, ARRAY[1018]::BIGINT[]),
    (493::BIGINT, 'Es bastante claro en sus explicaciones, es muy relajado en las evaluaciones. Me gustó los ejemplos que se hacía en clases.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2025-09-21T00:00:00+00:00'::TIMESTAMPTZ, '278e3d56efff24316d931bcd65f9a05f08001fc2e9580c61a6504c76b8113111'::TEXT, ARRAY[923]::BIGINT[]),
    (493::BIGINT, 'Apenas nos dió 2 semanas de clases, pero se ve la calidad de profesor. Muy claro y detallado en sus explicaciones. Profe, espero verte en otro curso más adelante. :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-08-17T00:00:00+00:00'::TIMESTAMPTZ, '3e04aabbf34a52bbcae463d6338b674ba2e902f6de45e745e331bf0f5320f0d0'::TEXT, ARRAY[563]::BIGINT[]),
    (493::BIGINT, 'Discreta es uno de los cursos más díficiles de mate, pero el profe te puede explicar desde lo más básico hasta lo complejo. Lo veo relax en las calificadas de los parciales. No te regala el curso, pero sí es accesible con sus evalaciones.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-04T00:00:00+00:00'::TIMESTAMPTZ, '9663e4dc38cd6e3d0afb4254df40646c615a636b830fcdeeadcd916e22bcd2ab'::TEXT, ARRAY[1018]::BIGINT[]),
    (493::BIGINT, 'De los profes que llevado de la escuela de matematica es el mejor profesor, da las clases muy claras y tiene muy buen dominio de la materia'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-06-25T00:00:00+00:00'::TIMESTAMPTZ, '88d38aa5403e1a97eb3349435728e2c0a02c1b7117046c90b197438b52ad6b46'::TEXT, ARRAY[935]::BIGINT[]),
    (493::BIGINT, 'El profesor Kendall es uno de los mejores docentes que tiene el TEC. Explica con claridad y paciencia, incluso temas que otros considerarían básicos. Sus quices son accesibles y siempre sube sus apuntes hechos en tablet a TecDigital.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-06-23T00:00:00+00:00'::TIMESTAMPTZ, '86e8f9c184d028b77a9098322646ac489ba72b0b9b92363c490a36693d904f9a'::TEXT, ARRAY[563]::BIGINT[]),
    (493::BIGINT, 'Los quices es muy pasable,npues lo saca de los apujtes de clases o prácticas que él deja. Y califica normal, los exámenes'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'a27af0b40b939be9ee495b13bbe93ab4196da7c3ecf7d108a9958a29510d8bf8'::TEXT, ARRAY[605]::BIGINT[]),
    (493::BIGINT, 'Es bastante relax con las evaluaciones suyas, sólo dejó tareas cortas, y califica accesible. En las clases explica lo necesario para el curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Pocos exámenes', 'Clases excelentes']::TEXT[], '2025-06-12T00:00:00+00:00'::TIMESTAMPTZ, '45d131bb3989e5b044ac70f2fec44890f62ac384dd658213b3c220cecc0ff103'::TEXT, ARRAY[935]::BIGINT[]),
    (493::BIGINT, 'Es un pro en Cálculo DI y CAL, enseña lo necesario e importante para los cursos. Es accesible en los quices y tareas, califica decente, y reconoce pts de procedimiento.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-05-05T00:00:00+00:00'::TIMESTAMPTZ, '679334a6141ec46d6305af010dea79e45fa4ac66a42a905b546fdb8a7f299923'::TEXT, ARRAY[1034]::BIGINT[]),
    (493::BIGINT, 'Nos trató muy bien con los quices y tareas, bastante accesible. Se aprende bastante en sus clases, y te pasa el material visto en clases.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-02-01T00:00:00+00:00'::TIMESTAMPTZ, '0bc5d36feb395372b8c87fdb755a8fb0de1098f4868093a73760d2fcb49a979d'::TEXT, ARRAY[935]::BIGINT[]),
    (493::BIGINT, 'Bastante provechosas sus clases. Explicaba ejercicios de exámenes viejos en sus clases, y eso nos preparaba al nivel del curso.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-01-22T00:00:00+00:00'::TIMESTAMPTZ, '784cad6cd25df8eafefe5ea1e9e43611911a7eff9db1b60657853a8e30763d7b'::TEXT, ARRAY[1057]::BIGINT[]),
    (493::BIGINT, 'He repetido este curso un par de ocasiones, y con el que mejor entiendo es con éste profe. Explica desde lo más básico hasta lo complejo. Las tareas son muy relax y cortos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-01-14T00:00:00+00:00'::TIMESTAMPTZ, '55b8cdd4d5ae6d91de7ef000531d05a198b3ce94fe1acd62af7451fa99259117'::TEXT, ARRAY[563]::BIGINT[]),
    (493::BIGINT, 'Explica bastante claro, cualquier tema del curso. Los quices y tareas son bastantes accesibles.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-12-14T00:00:00+00:00'::TIMESTAMPTZ, 'd0c22014f01fc298f3d6916dc78f9c89f6291442160ab09222db27da9db0d23b'::TEXT, ARRAY[935]::BIGINT[]),
    (493::BIGINT, 'Muy buen profesor que enseña claro y detallado, brinda material de apoyo (folletos) y utiliza las tecnologías actuales (apuntes virtuales y videos de ejercicios). Muy buena opción para discreta y solo toca prepararse un poco más para los exámenes, ya que cubre muy bien las bases.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-12-04T00:00:00+00:00'::TIMESTAMPTZ, '552bf428408268d0d9d2fae04e77e516805c0350a4bc96d38b25b67f1645ff2e'::TEXT, ARRAY[1018]::BIGINT[]),
    (493::BIGINT, 'Da buenos materiales escritos y vídeos para estudiar todos los temas. Es bastante claro en sus explicaciones. Muy recomendado, sí es la primera vez que lleva este curso.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Pocos exámenes', 'Clases excelentes']::TEXT[], '2024-11-23T00:00:00+00:00'::TIMESTAMPTZ, '074d86ce52e0343dfaa978f4f3e05840e094c3f0916faa9dae735f724925fde6'::TEXT, ARRAY[1018]::BIGINT[]),
    (493::BIGINT, 'Bastante relax con los quices y tareas. Califica normal, nada más prepararse un toque para los parciales. Es flexible para hacer clases virtuales a lo largo del semestre.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-13T00:00:00+00:00'::TIMESTAMPTZ, '89c46b0bbfa68b862ba46f8f533c1c66938cd0e8446889df7526c48183e8ce67'::TEXT, ARRAY[935]::BIGINT[]),
    (493::BIGINT, 'De los mejores en discreta'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2024-11-07T00:00:00+00:00'::TIMESTAMPTZ, 'b50c77e34e43dd95f56867b77ee4ab770d176d62f95ac031133a9d402867324e'::TEXT, ARRAY[1018]::BIGINT[]),
    (493::BIGINT, 'Es un curso bastante tranquilo. Si usted hace sus prácticas, sale bien con las tareas y quices. Te explica trucos útiles con la calcu.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2024-10-27T00:00:00+00:00'::TIMESTAMPTZ, 'cb7ddff1a684a285f803ee5a9d0866483ab0f3f9ef0707a838ee1d49329327f6'::TEXT, ARRAY[563]::BIGINT[]),
    (493::BIGINT, 'Muy tuanis el profe, hasta dejó quices extra para recuperar algunos pts de la nota. Le recomiendo estudiar bastante para el examen de series y sucesiones, lo demás es fácil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-10-15T00:00:00+00:00'::TIMESTAMPTZ, '383a2d8ee80c51b2c46bd7fbbc00fbdd73a06623429f30b1a51fa8f8d9c02701'::TEXT, ARRAY[634]::BIGINT[]),
    (493::BIGINT, 'Uno de los cursos de mate más complicados, pero el profe ayuda con quices extras y asistencia a clases. Explica bien y reconoce el esfuerzo del estudiante.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2024-10-03T00:00:00+00:00'::TIMESTAMPTZ, '49c670ae0e7ef4448962d37be533ecba19f78ec6e5f53d77f98c775283cc0b50'::TEXT, ARRAY[1049, 4836]::BIGINT[]),
    (493::BIGINT, 'Es bastante pro en MG. Explica algunos trucos con la calculadora que ayudan mucho en los parciales. Con lo visto en clases, se aprende bastante'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2024-09-25T00:00:00+00:00'::TIMESTAMPTZ, 'fae11ed8d988110e5787ee589cc3d8f7ce71534990899b9eaad603f305b2f8a8'::TEXT, ARRAY[563]::BIGINT[]),
    (493::BIGINT, 'Se la juega bastante en este curso. Sólo prepararse bien en el tema de Series (que es un toque díficil de entender a la primera); Quices y tareas accesibles'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-09-15T00:00:00+00:00'::TIMESTAMPTZ, '10a39a811c71064800bba11171035563cab20cf0e099df2b792c70873df0b0b6'::TEXT, ARRAY[634]::BIGINT[]),
    (493::BIGINT, 'Excelente profe: prepara muy bien sus clases. Los quices y tareas son relax.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Aspectos de calificación claros']::TEXT[], '2024-08-27T00:00:00+00:00'::TIMESTAMPTZ, 'baa6f1ee3ce7c98118bc8ac1fcf212371b84599a81c5a4e2006c61d30f39682d'::TEXT, ARRAY[563]::BIGINT[]),
    (493::BIGINT, 'CDI no es un curso fácil, pero este profe resuelva gran cantidad de ejercicios de buen nivel, entonces uno va afilado a los parciales.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-08-13T00:00:00+00:00'::TIMESTAMPTZ, '557593fa52a943dc931539dc2193003af37bfaaa19ad76946e520bb455640b68'::TEXT, ARRAY[923, 605, 634]::BIGINT[]),
    (493::BIGINT, 'Bastante tranquilo el curso, me gusto. Le recomiendo, ponerle bastante al primer examen de series. El profe nos trató tranquilo con tareas y revisa normal los parcial.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-07-13T00:00:00+00:00'::TIMESTAMPTZ, 'f1165f839a104d62afc80f4ba7cc3432bb6e0e9960619626ea6ad788a1c18f9d'::TEXT, ARRAY[634]::BIGINT[]),
    (493::BIGINT, 'Bastante carga el profe en sus clases. Este curso no es fácil, pero él te da las bases para trabajar con las demostraciones.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-07-05T00:00:00+00:00'::TIMESTAMPTZ, 'c09fb608157a1b84c0b7776d3da4a61190ea2f2b92fb80ac095c4596ac2240c3'::TEXT, ARRAY[1018]::BIGINT[]),
    (493::BIGINT, 'Las clases son muy largas y serias. Los quices son muy fáciles ya que son iguales a las prácticas que deja o los ejercicios del folleto. Es muy amable y las consultas provechosas. Si lo lleva con él haga las prácticas de cátedra porque los ejercicios que proporciona son muy fáciles.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '44b7fed07ff02072aeceb815ef31f12c9b7136f0646d85d7fad8cb2d7d01a060'::TEXT, ARRAY[563]::BIGINT[]),
    (493::BIGINT, 'El profe es muy bueno, él siempre intenta que todos entiendan, si usted no tiene bases, puede llevar con este profe, y si usted tiene bases el curso lo va a sentir fácil. Lo recomiendo mucho, sin embargo, a veces sus clases se sienten un poco largas.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'a97ccfc8060edebe85e50c63d0753970475aff26d4296000ca90da496a1f1730'::TEXT, ARRAY[563]::BIGINT[]),
    (493::BIGINT, 'Es un buen profesor solo que a veces no prepara muy bien para el examen entonces hay que hacer las prácticas de cátedra. En general califica muy suave entonces es casi de seguro que se pasa.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'f463b8259f5e3ad53d48cf6fa780bb9beaa44e0750ade3a92e8d5dcd644d03a9'::TEXT, ARRAY[563]::BIGINT[]),
    (493::BIGINT, 'Se la juega bastante en este curso. Brinda buenos materiales y vídeos de apoyo al curso. por lo que hace llevadero. Es tranquilo en la calificada, lo sentí normal.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-15T00:00:00+00:00'::TIMESTAMPTZ, '578cf58713e6a94758099200416be1af54b5a07d458c3e4705126d5b36b4c637'::TEXT, ARRAY[935]::BIGINT[]),
    (493::BIGINT, 'Excelente profesor. Súper recomendado, los folletos que utiliza durante el curso son súper útiles, explica de manera clara, califica bastante suave en los quizzes y si tiene dudas siempre contesta, sea en persona o por correo, el material del folleto siempre es igual al examen o al quiz.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'bf67a3240bb768bc7a6efc3e639b93eef21e889afde4768b2043d08f85140c0d'::TEXT, ARRAY[563]::BIGINT[]),
    (493::BIGINT, 'Discreta nunca es un curso fácil, pero este profe te da buena base para entender cualquier cosa. Sus materiales son bastantes buenos.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-04T00:00:00+00:00'::TIMESTAMPTZ, '6b481c8eeb5be10e8beb24aa816c5ca814585f54da651c2649a32ac15344faaf'::TEXT, ARRAY[1018]::BIGINT[]),
    (493::BIGINT, 'Hace quices bastantes accesibles y califica normal. Recomiendo bastantes sus apuntes y vídeos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-05-28T00:00:00+00:00'::TIMESTAMPTZ, 'ce5602717348f0b6e169ac9e81f78bc3018948046be3e14b49670df57bf551ea'::TEXT, ARRAY[935]::BIGINT[]),
    (493::BIGINT, 'Recomendado para Discreta. Explica claro y ejemplos muy buenos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-05-23T00:00:00+00:00'::TIMESTAMPTZ, '06d92c3d01bbef11e0ad34127f4eb37217f0a125af5b8c8936ccc5ac5570896c'::TEXT, ARRAY[1018]::BIGINT[]),
    (493::BIGINT, 'Explica super bien con sus materiales que son muy completos y útiles para los parciales. La cátedra es medianamente accesible, ni muy dífciles ni muy fáciles los exámenes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-05-14T00:00:00+00:00'::TIMESTAMPTZ, 'fbb085a463de7d93bc954c5beb1aefee9700f20ec6f5ea836cea5ab7d2d5c6f0'::TEXT, ARRAY[935]::BIGINT[]),
