    (493::BIGINT, 'Brinda bastante ejemplos prácticos y teóricos del curso. Con los apuntes del profe, me la jugué bastante en los parciales.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-05-06T00:00:00+00:00'::TIMESTAMPTZ, '194248d935f27ccd96999f2ae2c4d5ed9f5749a55d40c06664efe80047643fb5'::TEXT, ARRAY[1057]::BIGINT[]),
    (493::BIGINT, 'Tiene materiales bastantes completos y útiles para entender la materia. Con los exámenes, me va de maravilla. :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-04-20T00:00:00+00:00'::TIMESTAMPTZ, '0a366798caf896b633c8bf3e4a30683dfed1a3418ad16026454c281d710787a2'::TEXT, ARRAY[563]::BIGINT[]),
    (493::BIGINT, 'Bastante claro en sus clases y apuntes. Te preparan muy bien para los exámenes, siempre deja práctica muy similares y a nivel de exámenes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-04-01T00:00:00+00:00'::TIMESTAMPTZ, '7e99e68927a55e107531ade9e6b5e41c81d9d3729edf12bb72b3249b6e01509b'::TEXT, ARRAY[563]::BIGINT[]),
    (493::BIGINT, 'Vas aprender bastante con el profe.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2024-02-18T00:00:00+00:00'::TIMESTAMPTZ, '36e757687c943a726f3e53bb0768ad416082201a3875587f8f82995528833d56'::TEXT, ARRAY[923, 605, 634]::BIGINT[]),
    (493::BIGINT, 'Sabe explicar muy bien este curso. Lo malo, son los exámenes de cátedra que a veces se vuelan, pero el profe calificó normal.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-27T00:00:00+00:00'::TIMESTAMPTZ, '7d4d674fa539af3f3cbda620873eb8baf8c583e71937d56692757e0c54475080'::TEXT, ARRAY[634]::BIGINT[]),
    (493::BIGINT, 'Matrícule de una, sin miedo. Es un profe muy dedicado, y planea muy bien los materiales y ejercicios en clase. Te prepara a buen nivel, para los exámenes de cátedra.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-01-24T00:00:00+00:00'::TIMESTAMPTZ, 'f7fa0fad9c4e5d7e2f7148c6a67856b47f9242ea145cfbb428754e239f4fee14'::TEXT, ARRAY[563]::BIGINT[]),
    (493::BIGINT, 'He repetido este curso dos veces, y hasta ahora entiendo bien; hasta voy con buena nota en el curso. Excelente profe, y muy completos sus folletos y apuntes de clases.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'c7bf554a9d74e3ef32216400104bc57bfde75ac03964069e5d76a9a2bb3379a2'::TEXT, ARRAY[1018]::BIGINT[]),
    (493::BIGINT, 'Buen profesor, explica muy claro. Se preocupa que queden claros con la teoría.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-01-11T00:00:00+00:00'::TIMESTAMPTZ, '052133006a8715ecee1d6b723e4b31e969e3dd6ca7c9e57d15300d6f5256edd5'::TEXT, ARRAY[1018]::BIGINT[]),
    (493::BIGINT, 'El curso no es fácil, pero el profe explica bien y con bastantes ejemplos. A veces se puede tornar un poco larga las clases, pero abarca todo lo necesario para los parciales.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-07T00:00:00+00:00'::TIMESTAMPTZ, '9f163f6abf895f0eb7ad8c35f86c8937773d9c8d6f1ac2d93b45db45158a43d2'::TEXT, ARRAY[923, 605, 634]::BIGINT[]),
    (493::BIGINT, 'Bastante provechosas sus clases y ejemplos.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-03T00:00:00+00:00'::TIMESTAMPTZ, 'f3fb5d2d829e52a94681c8e601a4ea2c799f6178be630c76e623a04c8c072e96'::TEXT, ARRAY[1018]::BIGINT[]),
    (493::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-12T00:00:00+00:00'::TIMESTAMPTZ, '855fdb11df6b566a81f58368a05910959be0b7bcdad9a852323691decab414a8'::TEXT, ARRAY[1049, 4836]::BIGINT[]),
    (493::BIGINT, 'Brinda buenos ejemplos en clases. Hay que estudiar bien para los quices, pero califica suave.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-29T00:00:00+00:00'::TIMESTAMPTZ, '3c759c27108beb4e4acee2ee657f822cefe3cc3b80e9736a4179a59b100f21c4'::TEXT, ARRAY[605]::BIGINT[]),
    (493::BIGINT, 'Con las tareas es muy pura vida, explica super bien la materia, siempre te queda claro todo. En los parciales, te reconoce algo del procedimiento, si del todo no está bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-20T00:00:00+00:00'::TIMESTAMPTZ, '9366404c6d0842bcfca513efbac3108d10a97b1e78e03f2b6c3f504797d40371'::TEXT, ARRAY[634]::BIGINT[]),
    (493::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-11-12T00:00:00+00:00'::TIMESTAMPTZ, 'c5e9845126c6e2e36afd9fdbba4cf1cb2f9b46f83afe1c5a2bbb5b3571a37f12'::TEXT, ARRAY[563]::BIGINT[]),
    (493::BIGINT, 'Las tareas del profe son bastantes cortas y sencillas de realizar. Excelente dando los temas, con buenos ejemplos (nivel examen)'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-01T00:00:00+00:00'::TIMESTAMPTZ, '93b32347f2cb8c8bea4a30fc62c55c6e454f669ae28c10f4124eed99cd99dfaf'::TEXT, ARRAY[634]::BIGINT[]),
    (493::BIGINT, 'Muy bueno sus clases, muy respetable. No es tan rudo, calificando en los parciales. Hayque estudiar para los quices, pero si se sacan bien.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-10-29T00:00:00+00:00'::TIMESTAMPTZ, '018ef20175c2f5c91789cf81f025e1f12d702423c02d202a7da8fc5fff46619f'::TEXT, ARRAY[563]::BIGINT[]),
