    (493::BIGINT, 'No es un curso fácil, pero si usted revisa los apuntes del profe, y realiza ejercicios propuestos; te prepara muy bien a los parciales. Al final del curso, siempre ayuda a los que se esfuerzan y tuvieron interesados en el curso.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-09-25T00:00:00+00:00'::TIMESTAMPTZ, '7f7cf2b045b5da2fe6a2f807e461c5a96f71bda8ba119fbb56b735572f3b6553'::TEXT, ARRAY[923, 605, 634]::BIGINT[]),
    (493::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2023-09-15T00:00:00+00:00'::TIMESTAMPTZ, 'a79a8cd147d4a02c63ae9361ee1ef1a579479a6e9149abaaa062fd9985acd532'::TEXT, ARRAY[1018]::BIGINT[]),
    (493::BIGINT, 'Explica claro pero es redundante y complica mucho ejercicios y contenidos que en realidad son simples. Es grosero con los estudiantes, muy poco flexible, cree tener la razón en todo y califica realmente duro sin razón, sin valorar el razonamiento que el estudiante haya tenido. Fue lo peor.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2023-09-04T00:00:00+00:00'::TIMESTAMPTZ, '720680cac42f1eb1fb648037c931f2686531c04b77c1aa52c868180dd22c0ff2'::TEXT, ARRAY[1057]::BIGINT[]),
    (493::BIGINT, 'En clases trae ejemplos muy concretos y claros. Es bastante entendible, este profe.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-08-15T00:00:00+00:00'::TIMESTAMPTZ, '102f51eefd40c584f9ba889e4195147c7b82554f01719ea2a2690dc79b14170b'::TEXT, ARRAY[634]::BIGINT[]),
    (493::BIGINT, 'Explica muy claro. Baja muchos puntos por cosas que no se sabía que se iban a calificar. Hizo a una compañera asmática ir a dejar una tarea en persona porque no la dejó mandarla con alguien más. Da buena retroalimentación durante las consultas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Exámenes retadores']::TEXT[], '2023-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'cd25cf5b7edbd9774f72a94f02d1f2752a59510539b7cc02fdd13bc175305192'::TEXT, ARRAY[1057]::BIGINT[]),
    (493::BIGINT, 'En clases es bastante tranquilo, y dejaba hacer resúmenes como tareas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '23c5db24278de0c1a063ab3fffa6d20f62fb2973c9c1d4ceea7c35d13b9cf0d4'::TEXT, ARRAY[1018]::BIGINT[]),
    (493::BIGINT, 'Este profesor explica muy bien, pero califica como si se tratara de personas expertas en Estadística e incluso peor que si fuera así. Se inventa rubros para bajar puntos y es imposible que se eche para atrás con lo que sea. Siempre cree tener la razón, le grita a los estudiantes y es demasiado necio'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '31a7f7c0e28c89a3e0b0bd537ba2e43f1042192f6da89034cbd85d497eab9dd0'::TEXT, ARRAY[1057]::BIGINT[]),
    (493::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '502a7532868c1a125e4a24041947c06748411b73c37fc87be5614f1213654500'::TEXT, ARRAY[1057]::BIGINT[]),
    (493::BIGINT, 'Explica excelente, evalúa horrible, es demasiado piki, baja puntos por tonteras.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'ecddc80cd9ab9ec3c92f851f08f75528de20dddf387259085ec1a8ae4260f009'::TEXT, ARRAY[1057]::BIGINT[]),
    (493::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'e11f3b8fdac5049cedcc62fec89e864a023524d8b98a3f81fbe0cd6086b40256'::TEXT, ARRAY[1049]::BIGINT[]),
    (493::BIGINT, 'Es una buena opción para Proba, bastante organizado con la materia.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '8676e56c373848c1c0f1a3d7741cd7e18ab1d11548b92eb67c655069ab307222'::TEXT, ARRAY[1049]::BIGINT[]),
    (493::BIGINT, 'Un profe joven, pero sabe bastante. Explica con buen nivel para los exámenes.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, '619cae605b4af8854bc45ebdf5686f43cfb44ba7270a5e691b8b6e3da15f83c5'::TEXT, ARRAY[563]::BIGINT[]),
    (493::BIGINT, 'En este semestre sólo dejo tareas (no aplicó quices), entonces tuvo relativamente tranquilo con el profe. Lo feo son los exámenes de cátedra que a veces ponen ejercicios muy confusos.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-05T00:00:00+00:00'::TIMESTAMPTZ, '5e6d49836ec3a396b9e898bd130cf37fd27dc6f9c2ed75f615a7453fc4cea3be'::TEXT, ARRAY[1049]::BIGINT[]),
    (493::BIGINT, 'Yo llevé un par de cursos con él, y en clases es muy bueno. Quizás en algunas evaluaciones es un poco rudo con los ejercicios, pero se pueden resolver. Le doy un tip: al final del curso el profe siempre le ayuda con la nota final siempre que uno vaya a consulta y él vea que uno estaba interesado :)'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-01T00:00:00+00:00'::TIMESTAMPTZ, '6055ce6471dbc6d0ecbacb8ba060b64bcc6d6a59e36087c99a8b2d5335acdc08'::TEXT, ARRAY[605, 634]::BIGINT[]),
    (493::BIGINT, 'Este profe no debería tener una calificación tan alta. Ha tratado mal a estudiantes, califica muy duro y sin sentido. Convierte un curso fácil es un infierno solo porque sí. En las evaluaciones es todo paranóico con que uno está haciendo trampa. Y es grosero, además de muy poco flexible y accesible.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2023-05-27T00:00:00+00:00'::TIMESTAMPTZ, 'bfd0849d57ad14c012d38e12c42be619a5d6d9a9445cb1e5782b9b5e2f4c5174'::TEXT, ARRAY[1057]::BIGINT[]),
    (493::BIGINT, 'Sus clases de 4 horas tienden a ser muy pesadas, cero dinámicas y aburridas, ve toda la materia súper rápido y mete muchos temas a la vez que llegan a ser confusos. Los quices tienen un valor muy alto, y no se parecen para nada a los ejercicios que se realizaron en clase.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Muchos exámenes', 'Exámenes retadores']::TEXT[], '2023-05-25T00:00:00+00:00'::TIMESTAMPTZ, 'f55adec8137c159b7da7cc18ec05fa26aa3c6663ed8f13bd1d8f917ee71843bb'::TEXT, ARRAY[4836]::BIGINT[]),
    (493::BIGINT, 'El profesor hace clases de 4 horas donde solo él habla y nadie más participa, lo que se vuelve una clase muy pesada y cansada de mucha teoría y ejercicios. No presentó el cronograma de trabajo la primera semana de clases y después nos hizo quices 4 semanas seguidas y no accedió a cambiarlo.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-05-24T00:00:00+00:00'::TIMESTAMPTZ, '13d96f7d5567095f0a870e210d2b7fe2d8246a4babd2e458401fa4acb583aaa1'::TEXT, ARRAY[4836]::BIGINT[]),
    (493::BIGINT, 'si se valora como persona no meta con este mae, que no se le entiende nada y aparte mete varas que ni enseño el mae en los examenes y uno termina quebrado en la nota, aparte de ser clases extramadamente pesadas una clase minimo te mete 6 temas distintos y confusos de entender'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos exámenes', 'Exámenes retadores']::TEXT[], '2023-05-24T00:00:00+00:00'::TIMESTAMPTZ, '47d23c15e9b1e424bb1249d7aab86432b22c45db9a3f1f4f3add55e3ccb66d8b'::TEXT, ARRAY[4836]::BIGINT[]),
    (493::BIGINT, 'La verdad, muy buen profesor en sus clases. Tanto en sus quices y tareas trabaja con ejercicio nivel examen, entonces va muy fogueado para los exámenes.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-05-20T00:00:00+00:00'::TIMESTAMPTZ, 'e479f0ef8368a47c43ec908ab74ef5e307d955068184805cd4ff6895a4fdb9ec'::TEXT, ARRAY[563]::BIGINT[]),
    (493::BIGINT, 'La clase la da usando una tableta, por tanto, siempre nos pasa los apuntes vistos en clase. Maneja un equilibrio entre clases presenciales y virtuales. Me agrada la forma y enfoque que da este curso.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-04-19T00:00:00+00:00'::TIMESTAMPTZ, 'c38714fbbde62e23272d470efc68d828366c0ddb0ce974e0e5ad7a216b3d6041'::TEXT, ARRAY[1049]::BIGINT[]),
    (493::BIGINT, 'Se la juega bastante bien'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-04-13T00:00:00+00:00'::TIMESTAMPTZ, 'f6007adbfbe33b7b6bd7d8acad2e214764480ea15e6af9fe8fb2703cde49b250'::TEXT, ARRAY[563]::BIGINT[]),
    (493::BIGINT, 'Es un curso muy diferente a lo que se aprende en el cole. Pero logré pasar este curso a la primera, y el profe se la juega bastante, y hace ejemplos nivel examen. Sí lo recomiendo, si es primerizo'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2023-04-03T00:00:00+00:00'::TIMESTAMPTZ, 'df4d4aba7ee30c25414b17fe96e513191923d158f4970f6b37240ca0f679fced'::TEXT, ARRAY[1018]::BIGINT[]),
    (493::BIGINT, 'Explica muy bien el por qué de las fórmulas, y brinda buena cantidad de ejercicios en clases. El profe siempre trabaja a buen nivel tanto en clases como evaluaciones.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchos exámenes', 'Clases excelentes']::TEXT[], '2023-03-19T00:00:00+00:00'::TIMESTAMPTZ, 'f66e8b51dd44f01dad872a394b255003b19cc6d559d08d986fc9b6dc208b40a9'::TEXT, ARRAY[1057]::BIGINT[]),
    (493::BIGINT, 'En Verano es un curso muy intenso, recomendado para repitentes. El profe explicó super bien los temas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-03-14T00:00:00+00:00'::TIMESTAMPTZ, '1c1edb6c96b716d6d2dd9049a540dd89bdce7384788bd066194cd256bb6ea53a'::TEXT, ARRAY[605]::BIGINT[]),
    (493::BIGINT, 'Explica muy bien en Proba, y siempre nos pasa los apuntes de clase (usa una tableta).'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-02-27T00:00:00+00:00'::TIMESTAMPTZ, '09cbcb89fa5d9e88dcf5b700ddd1658e4ccb2fe0fbc8247a17b878c679141c69'::TEXT, ARRAY[1049, 4836]::BIGINT[]),
    (493::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-02-17T00:00:00+00:00'::TIMESTAMPTZ, 'db9eaef29679e0047f217de700d92aeba64e98969247d223a6852b1c983aa583'::TEXT, ARRAY[1018]::BIGINT[]),
    (493::BIGINT, 'La verdad que da el curso con un buen nivel. A mi me gustó la forma que trabaja con bastantes ejemplos.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-02-08T00:00:00+00:00'::TIMESTAMPTZ, '0b7a0c52c2d66137944e1d7b19e518a29d44166f4b92a35ffe858aba1eb9f240'::TEXT, ARRAY[605]::BIGINT[]),
    (493::BIGINT, 'La verdad, si se la juega bastante bien en el curso.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-01-29T00:00:00+00:00'::TIMESTAMPTZ, '0b3f78ac94baabf68d8c38754b96ca60588299a2445038f68f7163e94b0e8bca'::TEXT, ARRAY[1057]::BIGINT[]),
    (493::BIGINT, 'Nunca me había ido mal en una mate hasta que conocí este profe, explica súper mal, la materia es fácil si usted la estudia por aparte, sin embargo si se atiene a lo que el explica, no va a entender absolutamente nada'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-01-29T00:00:00+00:00'::TIMESTAMPTZ, '05bad38841cfaa866a23c2fc32d875d1d319f1c40c9377228896e5256fba0ff9'::TEXT, ARRAY[1049]::BIGINT[]),
    (493::BIGINT, 'Lo llevé en verano y el profe es una teja, todos los temas quedan super claros y está listo para ayudar siempre que uno lo necesite. Prepara demasiado bien las clases y va al punto.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-01-28T00:00:00+00:00'::TIMESTAMPTZ, '6bf1a595f5de31b706ab4fdbf67813f669497f6c639d7f38795a288e7c88d713'::TEXT, ARRAY[605]::BIGINT[]),
    (493::BIGINT, 'No es un curso fácil, pero el profe lleva buenos ejemplos en clase, y te prepara bien. Se necesita tener buenas bases algebraicas de ME y MG para no sufra tanto.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Muchos exámenes', 'Clases excelentes']::TEXT[], '2023-01-24T00:00:00+00:00'::TIMESTAMPTZ, 'd7a79ec3250ee40d52b64200d3e1942440dc80281eb022dc40b4817601a613ec'::TEXT, ARRAY[605]::BIGINT[]),
    (493::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-01-15T00:00:00+00:00'::TIMESTAMPTZ, '503d2c03a72a970c49c5feb67d117e5e8b938ac1edeade36f355cf92649c2de8'::TEXT, ARRAY[923, 605, 634]::BIGINT[]),
    (493::BIGINT, 'Explica muy bien la teoría necesaria, para realizar las demostraciones. No es un curso fácil, pero sin dudas, este profe da buenas bases para el curso.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-01-09T00:00:00+00:00'::TIMESTAMPTZ, '2a5ff091cfad81746f5933ff1bca79cb98b39aeb52d6b41492a4ff89e55fdf8b'::TEXT, ARRAY[1018]::BIGINT[]),
    (493::BIGINT, 'El profe va un toque rapido en las clases presenciales, pero se le entiende bien. Me gustó que algunos clases fueran virtuales, pues así teníamos los apuntes y grabaciones. El califica justo los quices, y a veces tenían pts extras.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2022-12-27T00:00:00+00:00'::TIMESTAMPTZ, '36de41f7571b0e79a06f1a3316e5c56dd64b5af86c22be147b6325240bcab70b'::TEXT, ARRAY[1049]::BIGINT[]),
    (493::BIGINT, 'Excelente opción para MG. Los ejercicios en clases y de tarea estaban a nivel de examen, y eso la ayuda a ir preparado para los quices y exámenes de la cátedra'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-12-21T00:00:00+00:00'::TIMESTAMPTZ, 'a9234e18b84fafe96c54da0e52a8c72f7ab66f3973d09759a8245e96697d0192'::TEXT, ARRAY[563]::BIGINT[]),
    (493::BIGINT, 'Un crack para Proba!!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2022-12-10T00:00:00+00:00'::TIMESTAMPTZ, 'f9ddf64a2927993a6ee3e7561563320182e1c4c716635987bdd9c4f1cc55698d'::TEXT, ARRAY[1049, 4836]::BIGINT[]),
    (493::BIGINT, 'No duden en matricular con él. Se aprende bastante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'd8366880020fe0c9d091ad5600bea5a45a768c1901716ee6330eb8109cad3e51'::TEXT, ARRAY[1057]::BIGINT[]),
    (493::BIGINT, 'Me gustó como da el curso de Cálculo con bastantes ejemplos y nivel de examen. Explica toda la teoría necesaria para entender un tema.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-30T00:00:00+00:00'::TIMESTAMPTZ, '8c27001366505423d8b672880eb0d169632b57228558f4ed905b26ea446dbb8b'::TEXT, ARRAY[605]::BIGINT[]),
