    (493::BIGINT, 'Pesimo profesor, tiende a culpar a los estudiantes de plagio solamente porque lograron una buena nota en los examenes, si pueden no matriculen con él.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-23T00:00:00+00:00'::TIMESTAMPTZ, '6bb278d8131c1bae3a52dc29cc7970c43012352a0af72525e39c99e077642982'::TEXT, ARRAY[1018]::BIGINT[]),
    (493::BIGINT, 'Super pro en Estadística, la parte práctica no es tan díficil, pero la parte teórica hay que estudiarla bien.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-18T00:00:00+00:00'::TIMESTAMPTZ, '60445cb0861ac3cb51f51438b8b329f511a6339fe97f35f9ed15737c5efee3dd'::TEXT, ARRAY[1057]::BIGINT[]),
    (493::BIGINT, 'Excelente profe!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-13T00:00:00+00:00'::TIMESTAMPTZ, 'a52a96c842837406c74d10ff1b048716a63c8654b34d33ee548dd237989eed63'::TEXT, ARRAY[923, 605, 634]::BIGINT[]),
    (493::BIGINT, 'Coincido con mensajes anteriores, es buena opción para Proba, al menos en Alajuela tenemos buenas referencias de él. Este semestre sólo trabajó con quices presenciales, pero los pts extras ayudan a mantener un buen promedio. Si pudiera matricular Estadística con él, lo haría sin pensarlo.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2022-11-13T00:00:00+00:00'::TIMESTAMPTZ, 'b89d793a8151fce37f309be4b45aed6f97acce0c233832e05be1972dafdc93b1'::TEXT, ARRAY[1049, 4836]::BIGINT[]),
    (493::BIGINT, 'De los mejores profes que he tenido, explica bien, da puntos extra y te prepara muy bien para los exámenes, en definitiva la mejor opción para llevar cursos pesados como Proba'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-12T00:00:00+00:00'::TIMESTAMPTZ, '89d4cd340819ca558fe6a964151dc1c1b9d6b09bcad93e03f85494135675b0fd'::TEXT, ARRAY[1049]::BIGINT[]),
    (493::BIGINT, 'El rubro de tareas fue muy fácil ganarse los pts. En virtualidad, explica muy bien con buenos ejercicios. Lo malo es que los exámenes no son fáciles, se necesita mucha práctica.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-02T00:00:00+00:00'::TIMESTAMPTZ, '1f4bde49583be0c5954c899bfe76cdb86f21657be4d013170a28d5a07fc140e0'::TEXT, ARRAY[1018]::BIGINT[]),
    (493::BIGINT, 'El peor profe que pude matricular, después de la evaluación docente, cambia, cuando ocupa que le explique lo hace de mal gana en consulta, no deja copiar los ejercicios de la diapositiva, explica demasiado rápido que ni da chance de tomar nota, cambia fechas de las evaluaciones a cada rato.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2022-10-26T00:00:00+00:00'::TIMESTAMPTZ, '8210a1f3490dbac20fc23cb5df5a872de12b67dddfa96e816ab6a2db068215e5'::TEXT, ARRAY[1049, 4836]::BIGINT[]),
    (493::BIGINT, 'Buen profesor, planea muy bien sus clases tanto en teoría y buena cantidad de ejemplos. Le gusta explicar ejercicios de nivel-examen, por tanto, si estudia sus ejercicios le puede ir muy bien en el examen.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-10-21T00:00:00+00:00'::TIMESTAMPTZ, 'f879182bb9fa74eb17d80bb57a2ed3afc137b592530a4d89ddad75e0cd2c8378'::TEXT, ARRAY[1057]::BIGINT[]),
    (493::BIGINT, 'Estaba llevando este curso por segunda vez, y se nota la gran diferencia de un buen curso. Con el profe van a aprender bastante de cálculo con suficientes ejemplos. 100% recomendado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Brinda apoyo']::TEXT[], '2022-10-17T00:00:00+00:00'::TIMESTAMPTZ, 'c3832b470bbd73c6c54182335a40c00ad1ec6d9b5e93cc1789b7b6da2f622a60'::TEXT, ARRAY[923, 605, 634]::BIGINT[]),
    (493::BIGINT, 'Excelente profe, conoce bastante del curso.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2022-10-03T00:00:00+00:00'::TIMESTAMPTZ, '70f34f45ece44dcb7bf1e0a40fba4a6331d5a618e6bc8a3e19efbcac34c9d446'::TEXT, ARRAY[1057]::BIGINT[]),
    (493::BIGINT, 'Es un profe que explica muy bien la teoría y buenos ejemplos. Califica justo los quices y exámenes'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2022-09-16T00:00:00+00:00'::TIMESTAMPTZ, '2281c8082a897ca723a0a4628ea6b7966d83254e590a58e61e10fca72440a58b'::TEXT, ARRAY[1049]::BIGINT[]),
    (493::BIGINT, 'Es la segunda vez que llevo Proba (pues la primera vez lo llevé con el profe malo de Proba, todos saben quién es). Y la verdad que a este profe todo se le entiende muy bien, está muy atento a las dudas por Telegram. El curso no es fácil, pero el profe le ayuda si uno muestra interés en el curso.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2022-09-04T00:00:00+00:00'::TIMESTAMPTZ, '95a3247eefaf6ae85cda7366de38245987ce65ecccf298d1489e8ba2e7e37d1f'::TEXT, ARRAY[1049, 4836]::BIGINT[]),
    (493::BIGINT, 'Explica todo muy bien. Es de los profes que agradecen el esfuerzo, si hace reuniones de explicación para exámenes da puntos extra por conectarse, en resúmenes bien hechos pone hasta 200 de nota y demás. Es muy fácil pasar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'e4b1244fc2015daa0d22f88ae596509b261a5a89640e5a42672595e202913884'::TEXT, ARRAY[563]::BIGINT[]),
    (493::BIGINT, 'Explica excelente y con muchos ejemplos. Suele asignar mas trabajos de lo usual pero son relacionados a la materia y resúmenes que son apuntes de las clases. Deja trabajos extra que ayudan a recuperar puntos. Realiza una reunión fuera de horario de clases para explicar para el exámen.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'e19a39a3408be9f8b4d5523eef66b9c14357b8f0fac42914a40ae42e291e7976'::TEXT, ARRAY[563]::BIGINT[]),
    (493::BIGINT, 'Recomendado, muy ordenado con sus apuntes y explicaciones. En tareas-resúmenes son pts ganados (incluyen pts extras que ayudan mucho).'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2022-06-05T00:00:00+00:00'::TIMESTAMPTZ, '0c780a880eda05af96a125fa39fe0ba54fce1a7a74abf9d6b7529d9b860141db'::TEXT, ARRAY[1018]::BIGINT[]),
    (493::BIGINT, 'Es ideal para que los llevan el curso por primera vez, pues explica muy bien cada detalle de los temas. Las prácticas que deja ayudan mucho a prepararse a los exámenes'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-05-26T00:00:00+00:00'::TIMESTAMPTZ, '0ab703fe370b8273b7b7bae0eb9b2b4b920e861ea544e2f0e8e0ddfba569f1ed'::TEXT, ARRAY[605]::BIGINT[]),
    (493::BIGINT, 'Sin hacer el último parcial, ya pasé el curso de lo bueno que son sus clases, llevaría de nuevo un curso con este profe'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-05-22T00:00:00+00:00'::TIMESTAMPTZ, 'e5c9d0281d415e29804b3d567a910117f0e4a7f83d6541395e27200bfe19148a'::TEXT, ARRAY[563]::BIGINT[]),
    (493::BIGINT, 'Buen profe, en general actualiza rápido las notas de evaluaciones, por eso, uno sabe cómo va en el curso'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-05-14T00:00:00+00:00'::TIMESTAMPTZ, 'bfbd5ea98e645fd10a47c93c15017a96566a2cd4b147c96c5caa51839a6561de'::TEXT, ARRAY[563]::BIGINT[]),
    (493::BIGINT, 'No dude en matricular con él, es excelente explicando!!!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-05-07T00:00:00+00:00'::TIMESTAMPTZ, 'f105a0e958e05bcfba683ce32d67bcc7ce5720d5473817165bda297841640260'::TEXT, ARRAY[634]::BIGINT[]),
    (493::BIGINT, 'Cuando lo llevé fue muy bueno, y se preocupa por los estudiantes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2022-05-03T00:00:00+00:00'::TIMESTAMPTZ, '90f15a3793589883604efa4f1342c9281d5d3b331ff485f8236622a0a1110344'::TEXT, ARRAY[923, 605, 634]::BIGINT[]),
    (493::BIGINT, 'Explica muy bien, y nos pide resúmenes como tarea (que son fáciles de hacer).'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-04-29T00:00:00+00:00'::TIMESTAMPTZ, '092d5f7f3cbc4f50acf6ec46a23e7817e3fb40e0fb5b95422c97d8d3cf51f6f3'::TEXT, ARRAY[1018]::BIGINT[]),
    (493::BIGINT, 'El curso no es fácil, pero el profe explica bien y con bastantes ejemplos. A veces, las clases son un poco largas pero explica toda la materia'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2022-04-29T00:00:00+00:00'::TIMESTAMPTZ, '331501c0cf624e63728399a3f0befa210e0f7ceae818cd5dd7aa2e569e9c6799'::TEXT, ARRAY[1018]::BIGINT[]),
    (493::BIGINT, 'No es de fiar, no da las instrucciones clara, si uno se confunde para él se esta burlandese, no hace más que intentar reprobarme y dificultarme las tareas'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2022-04-26T00:00:00+00:00'::TIMESTAMPTZ, '514f13e5bf403077fdc07227efa283f8289e330b64721f1f5c471444bf90c411'::TEXT, ARRAY[563]::BIGINT[]),
    (493::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-02-04T00:00:00+00:00'::TIMESTAMPTZ, '302967ff47e17b72eecf1583de638ff5a69b3a581b7c2c4742a79f3f976681cb'::TEXT, ARRAY[605]::BIGINT[]),
    (493::BIGINT, 'Muy buen profesor, explica muy claro, ayuda bastante, se preocupa por que los estudiantes entiendan y es muy buena gente, lo recomiendo mucho.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'd0498fda7db7fd3ac99db10dd363116743758014728ff2f17e7065c1b804397a'::TEXT, ARRAY[563]::BIGINT[]),
    (493::BIGINT, 'Le aplaudo su organización con la materia sin embargo es un profe con poca esperiencia a pesar de conoce mucho de los temas se suele enrredar con bastante frecuencia, NO RESPETA HORARIOS, se sobrepasa hasta un hora extra de la clase, y tiende a tener entre ojos a algunos estudiantes.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2022-01-27T00:00:00+00:00'::TIMESTAMPTZ, 'fdeaa237ad739de8a226158e5e08fabf137583ace488039f8b1df2d0056ac325'::TEXT, ARRAY[563]::BIGINT[]),
    (493::BIGINT, 'Explica demasiados ejemplos. Eso hace que las clases sean muuuuuuy largas y el profe no respeta e horario de la misma, pero el monton de ejemplos sí ayuda a preparar mucho para los exámenes de la cátedra. El profe manda prácticas que ayudan a practicar y es DEMASIADO organizado.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Da crédito extra']::TEXT[], '2022-01-20T00:00:00+00:00'::TIMESTAMPTZ, 'a643c3bb03ffe65cd87cafeb34e41fa9d78bb7915cc626b9fb4ea74166ec0ad5'::TEXT, ARRAY[605]::BIGINT[]),
    (493::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, '046a91bcb6653627444d167000d3c2bbecc7656d6975dd5b29ddb70a0e272dfa'::TEXT, ARRAY[605]::BIGINT[]),
    (493::BIGINT, 'Virtual. El profe es bueno en lo que hace, conoce bastante y se nota, falta experiencia pero eso a su tiempo va a ir cambiando. Debo decir que no lleven la clase con él si se distraen facilmente, las clases son el 30% explicando materia y 70% resolviendo ejercicios sin respetar el horario de clase.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros']::TEXT[], '2021-11-29T00:00:00+00:00'::TIMESTAMPTZ, '721b242e0f86f6aed09a436317a4797e639b77414eb86148a27f1e6985b35829'::TEXT, ARRAY[605]::BIGINT[]),
    (493::BIGINT, 'Las clases duran mucho y puede llegar a pasarse de la hora, pero es muy buen profe, explica claramente y hace muchos ejercicios que ayudan mucho. Llevaría todas las clases con él. Los que lo califican mal de fijo lo están calificando con cólera jajajaj.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-29T00:00:00+00:00'::TIMESTAMPTZ, '625fde72a85dc2c42a2342fc0b12b6d07ba76c9623addc604aa14f5742aa402f'::TEXT, ARRAY[605]::BIGINT[]),
    (493::BIGINT, 'Es un profesor con quien yo no tomaría su clase otra vez, es lo peor de lo peor, se cree la octava maravilla del universo y desde las primeras semanas, se las agarra en contra de ciertos estudiantes sin ninguna razón. Definitivamente, matriculen con alguien más, vale la pena.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2021-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'c936538e4246c15eb9fd2bf7bce12153e418b07c2fbe00c73f792dae4c2321ba'::TEXT, ARRAY[923, 605, 634]::BIGINT[]),
    (493::BIGINT, 'No lo recomiendo como profesor, las explicaciones no son claras, se enreda el mismo con la materia, y siemre se pasa al menos unos 30 min de la hora de salida de clases, por lo que rara vez respeta los horarios como recesos y demás.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2021-11-17T00:00:00+00:00'::TIMESTAMPTZ, '52ddcbad5ddc1e29e282f06a34c354fb602d7c58df72056f13e49e129b9dc13a'::TEXT, ARRAY[605]::BIGINT[]),
    (493::BIGINT, 'Es un profe que entiende a los estudiantes, sus clases un poco aburridas y largas pero literal con el pasas de fijo el curso de mate que sea, es un profe súper buena nota y atiende a todas las dudas, siempre es atento y si ocupa consulta el estará siempre con disponibilidad'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2021-08-18T00:00:00+00:00'::TIMESTAMPTZ, 'd0ffff8262da4117576de58592c88db5a1870f9514b65f6f24397d2edfe6da72'::TEXT, ARRAY[563]::BIGINT[]),
    (493::BIGINT, 'Un excelente profe, le falta recorrido (experiencia), pero es un gran profe es súper comprensible, si le pones el te ayudará, es un poquito aburrido porque habla lento, pero lo recomiendo muchísimo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Da crédito extra']::TEXT[], '2021-07-26T00:00:00+00:00'::TIMESTAMPTZ, '5eb9cdeaaf08003abc66af2720d384365c2a6a87ef5814d3f3cc5085ede4dc3f'::TEXT, ARRAY[634]::BIGINT[]),
    (493::BIGINT, 'El profe es bueno, aveces se enreda mucho pero al final de cuentas si pones atención a la clase te va good'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Brinda apoyo']::TEXT[], '2021-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'd8c11fc6d1a4921594976dc14c02c4ad6dadfdcba9392178d4c714be35367201'::TEXT, ARRAY[1018, 563]::BIGINT[]),
    (493::BIGINT, 'Explica muy bien, deben poner demasiada atención(lo normal en los cursos), es muy amable, sí llega a ser estricto o se enoja si ve a gente despreocupada o sin interés en la clase, las tareas son muchas pero claras, ayuda un poco sobre ellas quizá si tienen un ejercicio reto muy difícil,inspirador.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2021-07-18T00:00:00+00:00'::TIMESTAMPTZ, 'f64abf1b46d6a0f30e316818d6b0f361ce9c289780c19e168651ff12d241713d'::TEXT, ARRAY[563]::BIGINT[]),
    (493::BIGINT, 'Se preocupa mucho, tareas un poco largas pero se pueden hacer en pareja y preparan mucho para las evaluaciones. Cualquier tarea moral o práctica extra que deje hágala porque él recompensa el esfuerzo extra. Prepara bien la clase y todo lo lleva en orden (Google classroom). Dele sin miedo!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2021-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'fdf8c48c14a405db2e9308e126ceb810ab9206445a33a8c680517312c75b836c'::TEXT, ARRAY[634]::BIGINT[]),
    (493::BIGINT, 'Explica muy bien Hace muchos ejemplos en clase Deja prácticas que ayudan mucho a los quices y exámenes Las tareas son fáciles'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-24T00:00:00+00:00'::TIMESTAMPTZ, '44f9bea2ba8d92340cf6d5f547d49e6dcda696fb4f0cace2625f9dc37f26d3d4'::TEXT, ARRAY[634]::BIGINT[]),
    (493::BIGINT, 'Es un profe que ayuda mucho si uno participa, da puntos extras en las tareas que pueden salvarle la tanda a uno. Suele brindar resúmenes muy buenos y las tareas son muy similares a las evaluaciones.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, '4db2a56359f7c9fbb4d3504193b8ea5b9da5dd1c1c63753d1361d61cdc8686e8'::TEXT, ARRAY[634]::BIGINT[]),
    (493::BIGINT, 'Muy buen profesor, las clases las toma en serio para explicar todo, deja todo muy claro haciendo ejercicios de nivel de examen. No duden en matricular con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, '8fc6a215cf7f1559c89bda2cf61169cb2780dcf0e91aec43ce0e1f7b2abaabb2'::TEXT, ARRAY[634]::BIGINT[]),
    (493::BIGINT, 'Es un buen profe, pero mi cursos era básico quizá en un curso más pesado no sea tan bueno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2021-04-09T00:00:00+00:00'::TIMESTAMPTZ, 'de83678ca7f4cbdee7b7206db370d0302dbc7d00e545c5ee2e8891fe77c99b1b'::TEXT, ARRAY[563]::BIGINT[]),
    (493::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-03-17T00:00:00+00:00'::TIMESTAMPTZ, '1f2e36247d148bf47a3fa2b4385301120a52b9fc5700df2cbe4d878aa2a2143f'::TEXT, ARRAY[634]::BIGINT[]),
    (493::BIGINT, 'Apenas en semana 2 dejé de ir a clases por lo que me pasaron videos de otro profe. No se le entiende absolutamente nada y se enreda bastante La verdad no se porque lo ponen a dar cursos difíciles'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-03-02T00:00:00+00:00'::TIMESTAMPTZ, '7297b879bd34ff6e3f63994135f0e2bae48590269fd9299c1be0ca29eca7d021'::TEXT, ARRAY[634]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
